export function mountRegimeWatch({data,openDialog,sourceList,esc,fmt,icon,selectMetric}){
  const root=document.getElementById('regime-watch');
  const research=data.regime;
  if(!research){root.hidden=true;return;}
  const metric=id=>data.metrics.find(m=>m.id===id);
  const sourceButton=(ids,label='Sources')=>`<button class="regime-source-button" data-regime-sources="${ids.join(',')}">${icon('book')} ${esc(label)}</button>`;
  const flowArrow=reverse=>`<svg class="fee-direction ${reverse?'reverse':''}" viewBox="0 0 70 20" aria-hidden="true"><path d="M2 10h64M59 4l7 6-7 6"/></svg>`;
  root.innerHTML=`<div class="regime-head"><div><div class="eyebrow muted">REGIME WATCH · RESEARCH THESIS</div><h2 id="regime-heading">When the old economics reverse.</h2></div><span class="regime-evidence-badge">Fee reversal observed</span></div><p class="regime-deck">The processing-fee relationship has reversed. Track who captures the value, and what could change it.</p><div class="regime-tabs" role="tablist" aria-label="Explore the copper smelting reversal"><button id="regime-tab-evidence" role="tab" aria-selected="true" aria-controls="regime-body" tabindex="0" data-regime-tab="evidence">The reversal</button><button id="regime-tab-exposures" role="tab" aria-selected="false" aria-controls="regime-body" tabindex="-1" data-regime-tab="exposures">Who benefits</button><button id="regime-tab-signals" role="tab" aria-selected="false" aria-controls="regime-body" tabindex="-1" data-regime-tab="signals">What to watch</button></div><div id="regime-body" class="regime-body" role="tabpanel" aria-labelledby="regime-tab-evidence"></div><div class="regime-bottom"><span>${icon('clock')} Verified 25 Nov 2026 · research snapshot</span><button class="regime-source-button" data-regime-notes>${icon('info')} Thesis & source notes</button></div>`;
  const body=root.querySelector('#regime-body');
  function evidence(){const tc=metric('tc'),acid=research.cases.acidSeller,buyer=research.cases.acidBuyer;return `<div class="regime-proof-grid"><article class="regime-proof"><div class="regime-proof-label">THE FEE RELATIONSHIP</div><h3>Scarce concentrate changes the terms.</h3><div class="fee-flow"><div class="flow-caption">Traditional positive TC</div><div class="fee-flow-row"><span>Miner</span><div>${flowArrow(false)}<small>processing fee</small></div><span>Smelter</span></div><div class="flow-caption now">Negative spot TC</div><div class="fee-flow-row flipped"><span>Miner</span><div>${flowArrow(true)}<small>fee benefit reverses</small></div><span>Smelter</span></div></div><div class="regime-price"><strong>$${fmt(tc.value,2)}</strong><span>per dry tonne · spot TC<br>6 Nov 2026 · older public quote</span></div><p>A negative TC improves the miner's concentrate proceeds and reduces the smelter's processing income.</p><div class="regime-benchmark"><strong>$0/t</strong><span>2026 annual TC benchmark.<br>Separate from the spot assessment.</span></div><div class="proof-footer">${sourceButton(['argus','regimeIEA'],'Fee evidence')}</div></article><article class="regime-proof"><div class="regime-proof-label">THE BY-PRODUCT OFFSET</div><h3>Acid can cover the smelting bill.</h3><div class="case-caption">${esc(acid.company)} · ${esc(acid.period)}</div><div class="acid-comparison"><div class="acid-bar-label"><span>Acid by-product credit</span><strong>$${fmt(acid.credit,2)}</strong></div><div class="acid-track"><span class="acid-credit" style="width:${acid.credit/.8*100}%"></span></div><div class="acid-bar-label"><span>Smelter operating cost</span><strong>$${fmt(acid.cost,2)}</strong></div><div class="acid-track"><span class="acid-cost" style="width:${acid.cost/.8*100}%"></span></div><div class="acid-unit">${esc(acid.unit)}</div></div><div class="offset-result"><strong>${fmt(acid.credit/acid.cost,2)}×</strong><span>coverage of this smelter operating-cost line<br>Calculated from company disclosures.</span></div><p class="case-limit">Selected cash-cost components, not the mine's total cost or profit margin. DRC results do not establish Chinese plant margins.</p><div class="proof-footer">${sourceButton([acid.source],'Company disclosure')}</div></article></div><div class="acid-buyer-case"><span class="buyer-symbol">${icon('acid')}</span><div><h3>The same acid can hurt its buyer.</h3><p>Mantos Blancos, Chile: acid prices were <strong>$${fmt(buyer.current)}/t</strong> in Q3 2026 versus <strong>$${fmt(buyer.previous)}/t</strong> a year earlier. Capstone also reduced acid-intensive heap throughput at Mantoverde.</p><span class="case-caption">Separate sites and periods from the Chinese acid index.</span></div>${sourceButton([buyer.source],'Cost evidence')}</div><p class="regime-timing">${esc(research.timing)} The IEA dates negative spot fees to 2024 and the zero annual benchmark to 2026.</p>`;}
  function exposures(){return `<div class="exposure-intro"><h3>Follow the business model.</h3><p>These are conditional economic exposures. Share-price returns also depend on valuation and expectations.</p></div><div class="exposure-grid">${research.exposures.map(actor=>`<article class="exposure-card"><span class="exposure-tag ${esc(actor.tone)}">${esc(actor.tag)}</span><h3>${esc(actor.business)}</h3><p>${esc(actor.mechanism)}</p><div class="exposure-check"><strong>Check before acting</strong><span>${esc(actor.verify)}</span></div>${sourceButton(actor.sourceIds,'Supporting evidence')}</article>`).join('')}</div><div class="opportunity-note"><strong>A business advantage needs an investment case.</strong><p>Check contract exposure, full costs, balance-sheet strength, valuation and a catalyst. These six indicators cannot establish that an asset is mispriced.</p></div>`;}
  function signals(){const signals=[
    {id:'tc',name:'Spot concentrate TC / RC',value:'$'+fmt(metric('tc').value,2)+'/dmt',date:'6 Nov · older quote',read:'Negative fees confirm the processing reversal.',challenge:'Fees recovering toward zero would reduce the miner advantage and ease processing pressure.'},
    {id:'acid',name:'Chinese sulphuric acid',value:'¥'+fmt(metric('acid').value,1)+'/t',date:'6 Nov · older quote',read:'The last public quote fell ¥15/t WoW, weakening the by-product cushion.',challenge:'Current net acid proceeds and plant costs are needed to test whether that cushion persists.'},
    {id:'production',name:'Chinese refined production',value:'1.0867 Mt · SMM',date:'Oct 2026',read:'SMM fell 3.03% MoM; NBS rose 1.80% YoY on a separate 1.2220 Mt series.',challenge:'Sustained cuts within the same dataset would strengthen evidence of capacity adjustment.'},
    {id:'imports',name:'Concentrate imports',value:'2.1670 Mt',date:'Oct 2026',read:'January–October imports fell 3.80% YoY on a gross-material basis.',challenge:'Higher concentrate arrivals could ease feedstock competition; grades and contained copper still matter.'},
    {id:'inventory',name:'SHFE inventories',value:fmt(metric('inventory').value)+' t',date:'20 Nov 2026',read:'Stocks rose 3,204 t WoW, a counter-signal to immediate physical scarcity.',challenge:'Persistent stock builds would weaken the squeeze thesis; renewed draws would strengthen it.'},
    {id:'premium',name:'Yangshan warrant premium',value:'$'+fmt(metric('premium').value)+'/t',date:'25 Nov 2026',read:'The latest daily assessment fell $50/t, showing a retreat in this import premium.',challenge:'A sustained premium rebound would support tighter import conditions; further declines would weaken that reading.'}
  ];return `<div class="signal-intro"><span class="exposure-tag mixed">Mixed physical signals</span><h3>A fee reversal is not an automatic copper rally.</h3><p>Interpretations below are research judgments. Latest observation dates differ; there is no live alert or trading score.</p></div><div class="regime-signal-table"><table><thead><tr><th>Indicator & observation</th><th>Current interpretation</th><th>What could change the reading</th></tr></thead><tbody>${signals.map(s=>`<tr><td data-label="Indicator & observation"><button class="signal-metric-button" data-regime-metric="${s.id}">${esc(s.name)}</button><strong class="signal-number">${esc(s.value)}</strong><span class="signal-date">${esc(s.date)}</span></td><td data-label="Current interpretation">${esc(s.read)}</td><td data-label="What could change the reading">${esc(s.challenge)}</td></tr>`).join('')}</tbody></table></div><div class="opportunity-note"><strong>The strongest test is a company earnings bridge.</strong><p>Compare concentrate terms, by-product proceeds, premiums and operating costs for the same company and reporting period. Do not subtract a CNY/t acid quote from a USD/dmt concentrate charge.</p></div>`;}
  function bindButtons(){root.querySelectorAll('[data-regime-sources]').forEach(button=>button.addEventListener('click',()=>{const ids=button.dataset.regimeSources.split(',');openDialog(`<h2 class="dialog-title">Evidence behind the reversal.</h2><p class="dialog-lead">Published facts support the mechanism. Opportunity assessments are interpretations, not demonstrated investment returns.</p>${sourceList(ids)}`);}));root.querySelectorAll('[data-regime-metric]').forEach(button=>button.addEventListener('click',()=>selectMetric(button.dataset.regimeMetric)));}
  function render(tab){root.querySelectorAll('[data-regime-tab]').forEach(button=>{const active=button.dataset.regimeTab===tab;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;});body.setAttribute('aria-labelledby','regime-tab-'+tab);body.innerHTML=tab==='evidence'?evidence():tab==='exposures'?exposures():signals();bindButtons();}
  root.querySelectorAll('[data-regime-tab]').forEach((button,index)=>{button.addEventListener('click',()=>render(button.dataset.regimeTab));button.addEventListener('keydown',event=>{const tabs=[...root.querySelectorAll('[data-regime-tab]')];let next;if(event.key==='ArrowRight')next=(index+1)%tabs.length;else if(event.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();render(tabs[next].dataset.regimeTab);tabs[next].focus();});});
  root.querySelector('[data-regime-notes]').addEventListener('click',()=>openDialog(`<h2 class="dialog-title">The reversal thesis.</h2><div class="detail-block"><h3>What the evidence establishes</h3><p>Processing fees can reverse and by-product income can materially change plant economics. Negative TC alone does not establish a smelter's total loss, an economy-wide shortage, or an investment return.</p></div><div class="detail-block"><h3>What would invalidate a simple trade</h3><p>Fee recovery, cheaper by-products, new concentrate supply, persistent inventory builds, or a valuation that already reflects the advantage can change the case. Integrated producers may sit on both sides of the relationship.</p></div><div class="detail-block"><h3>Timing and geography</h3><p>${esc(research.timing)} Company examples from the DRC, Chile and Europe illustrate the mechanisms. They are not direct estimates of Chinese plant profitability.</p></div>${sourceList(research.sourceIds)}`));
  render('evidence');
}
